import Foundation

public protocol RouteAtlasProviding: Sendable {
    func routeAtlas() async throws -> RouteAtlas
}

/// Loads the route atlas generated by `scripts/route_atlas/build.py` from the app bundle.
public struct BundledRouteAtlasService: RouteAtlasProviding {
    public static let resourceName = "route-atlas"

    private let url: URL?

    public init(url: URL? = BundledRouteAtlasService.defaultURL) {
        self.url = url
    }

    public static var defaultURL: URL? {
        #if SWIFT_PACKAGE
        Bundle.module.url(forResource: resourceName, withExtension: "json")
        #else
        Bundle.main.url(forResource: resourceName, withExtension: "json")
        #endif
    }

    public func routeAtlas() async throws -> RouteAtlas {
        guard let url else { throw RailDataError.unavailable }
        let data = try Data(contentsOf: url)
        return try RouteAtlasDecoder.decode(data)
    }
}

/// Decodes the compact atlas JSON (encoded polylines, short city IDs) into model values.
public enum RouteAtlasDecoder {
    public static func decode(_ data: Data) throws -> RouteAtlas {
        let file = try JSONDecoder().decode(AtlasFile.self, from: data)
        let cities = file.cities.map {
            AtlasCity(
                id: $0.id,
                name: $0.name,
                region: $0.region,
                coordinate: RailCoordinate(latitude: $0.lat, longitude: $0.lon),
                isFreightHub: $0.freightHub
            )
        }
        let routes = file.passengerRoutes.map { route in
            PassengerRoute(
                id: route.id,
                name: route.name,
                railOperator: RailOperator(rawValue: route.operator) ?? .amtrak,
                kind: route.kind,
                originID: route.from,
                terminusID: route.to,
                miles: route.miles,
                stops: route.stops.map { PassengerRoute.Stop(cityID: $0.city, mile: $0.mile) },
                path: Polyline.decode(route.path)
            )
        }
        // Track pieces are shared by every hub's tree on the same railroad; decode each once.
        var pieces: [String: [[RailCoordinate]]] = [:]
        for track in file.freightTrack {
            pieces[track.railroad] = track.pieces.map(Polyline.decode)
        }
        let networks = file.freightNetworks.compactMap { network -> FreightNetwork? in
            guard let railroad = RailOperator(rawValue: network.railroad) else { return nil }
            let track = pieces[network.railroad] ?? []
            return FreightNetwork(
                railroad: railroad,
                hubID: network.hub,
                branches: network.branches.map {
                    FreightNetwork.Branch(
                        parent: $0.parent >= 0 ? $0.parent : nil,
                        weight: $0.weight,
                        endCityIDs: $0.ends,
                        path: assemble($0.pieces, from: track)
                    )
                }
            )
        }
        let pairs = file.freightPairs.compactMap { pair -> FreightPair? in
            guard let railroad = RailOperator(rawValue: pair.railroad) else { return nil }
            return FreightPair(railroad: railroad, fromID: pair.from, toID: pair.to, miles: pair.miles, via: pair.via)
        }
        return RouteAtlas(
            cities: cities,
            passengerRoutes: routes,
            freightNetworks: networks,
            freightPairs: pairs,
            sources: file.sources
        )
    }

    /// Joins signed piece references (k + 1 = piece k as stored, -(k + 1) = reversed) into one path.
    static func assemble(_ references: [Int], from pieces: [[RailCoordinate]]) -> [RailCoordinate] {
        var path: [RailCoordinate] = []
        for reference in references {
            let index = abs(reference) - 1
            guard pieces.indices.contains(index) else { continue }
            let piece = reference > 0 ? pieces[index] : pieces[index].reversed()
            path.append(contentsOf: path.last == piece.first ? piece.dropFirst() : piece[...])
        }
        return path
    }

    private struct AtlasFile: Decodable {
        let sources: [String]
        let cities: [City]
        let passengerRoutes: [Route]
        let freightTrack: [Track]
        let freightNetworks: [Network]
        let freightPairs: [Pair]
    }

    private struct City: Decodable {
        let id: String
        let name: String
        let region: String
        let lat: Double
        let lon: Double
        let freightHub: Bool
    }

    private struct Route: Decodable {
        struct Stop: Decodable {
            let city: String
            let mile: Int
        }

        let id: String
        let name: String
        let `operator`: String
        let kind: PassengerRoute.Kind
        let from: String
        let to: String
        let miles: Int
        let stops: [Stop]
        let path: String
    }

    private struct Track: Decodable {
        let railroad: String
        let pieces: [String]
    }

    private struct Network: Decodable {
        struct Branch: Decodable {
            let parent: Int
            let weight: Int
            let ends: [String]
            let pieces: [Int]
        }

        let railroad: String
        let hub: String
        let branches: [Branch]
    }

    private struct Pair: Decodable {
        let railroad: String
        let from: String
        let to: String
        let miles: Int
        let via: [String]
    }
}

/// Google encoded polyline format, precision 5.
public enum Polyline {
    public static func decode(_ encoded: String) -> [RailCoordinate] {
        var coordinates: [RailCoordinate] = []
        var latitude = 0
        var longitude = 0
        var bytes = encoded.utf8.makeIterator()

        func next() -> Int? {
            var result = 0
            var shift = 0
            while let byte = bytes.next() {
                let value = Int(byte) - 63
                result |= (value & 0x1F) << shift
                shift += 5
                if value < 0x20 {
                    return (result & 1) != 0 ? ~(result >> 1) : result >> 1
                }
            }
            return nil
        }

        while let deltaLatitude = next(), let deltaLongitude = next() {
            latitude += deltaLatitude
            longitude += deltaLongitude
            coordinates.append(RailCoordinate(latitude: Double(latitude) / 1e5, longitude: Double(longitude) / 1e5))
        }
        return coordinates
    }
}
